// <diletta-file-card> — a INSTÂNCIA WEB de `design-system-file-card`.
//
// No Figma ele é o conjunto `Drop-file`, com um eixo `State` de cinco valores — e
// `Upload State` nunca foi um segundo nome: é a variante `State=view upload`.
//
// O CARTÃO VAZIO É O MESMO CARTÃO, e isto foi medido em 08/09 depois de eu
// declarar o contrário. `State=Default` tem a mesma anatomia do cheio — medalhão
// de 36, linha de rótulo, linha de apoio, botão de ícone — e o que muda é o
// conteúdo: glifo de seta pra cima, a instrução no lugar do nome do arquivo, e o
// menu desligado. Eu tinha declarado isso como «peça faltando»; a medição diz
// EIXO faltando, que é uma ordem de grandeza mais barata.
//
// > A anatomia é a mesma; o que muda é o conteúdo. Isso é variante, não peça.
//
// `Uploading` e `Error` existem publicados e têm ZERO instâncias no produto, então
// não entram: valor de eixo só entra com instância contada.
const ALTURA = { anexado: 154, vazio: 152 };
const PREVIA = ['imagem', 'glifo'];
const ESTADO = ['anexado', 'vazio'];

const SETA_ACIMA =
  '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">' +
  '<path d="M12 16V4m-5 5l5-5 5 5M4 17v2a2 2 0 002 2h12a2 2 0 002-2v-2" ' +
  'stroke="currentColor" stroke-width="1.5" fill="none" stroke-linecap="round" ' +
  'stroke-linejoin="round"/></svg>';

const ARQUIVO =
  '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">' +
  '<path d="M14 3v5h5M14 3H7a2 2 0 00-2 2v14a2 2 0 002 2h10a2 2 0 002-2V8l-5-5z" ' +
  'stroke="currentColor" stroke-width="1.5" fill="none" stroke-linejoin="round"/></svg>';

class DilettaFileCard extends HTMLElement {
  static observedAttributes =
    ['estado', 'previa', 'nome', 'apoio', 'formato', 'tamanho', 'foto', 'href'];

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this.render(); }
  attributeChangedCallback() { if (this.shadowRoot) this.render(); }

  get estado() {
    const v = this.getAttribute('estado');
    return ESTADO.includes(v) ? v : 'anexado';
  }

  get previa() {
    const v = this.getAttribute('previa');
    if (PREVIA.includes(v)) return v;
    return this.getAttribute('foto') ? 'imagem' : 'glifo';
  }

  /// Corta no MEIO preservando a extensão. Cortar no fim entrega
  /// "Documento_qual…" e a pessoa perde a única parte que distingue um anexo do
  /// outro numa lista.
  static elide(nome, teto = 28) {
    if (nome.length <= teto) return nome;
    const p = nome.lastIndexOf('.');
    const ext = p > 0 ? nome.slice(p) : '';
    const base = p > 0 ? nome.slice(0, p) : nome;
    const sobra = Math.max(4, teto - ext.length - 1);
    const ini = Math.ceil(sobra / 2), fim = Math.floor(sobra / 2);
    return `${base.slice(0, ini)}…${base.slice(base.length - fim)}${ext}`;
  }

  render() {
    const vazio = this.estado === 'vazio';
    const nome = this.getAttribute('nome') || '';
    const formato = this.getAttribute('formato') || '';
    const tamanho = this.getAttribute('tamanho') || '';
    const apoio = this.getAttribute('apoio')
      || [formato, tamanho].filter(Boolean).join(' \u00b7 ');
    const foto = this.getAttribute('foto');

    // A altura é 154 nos dois casos com anexo: arquivo que não é imagem não tem o
    // que mostrar, e um cartão que encolhe nesse caso quebra o alinhamento de uma
    // lista mista. O vazio é 152, medido — ele não tem a faixa de prévia.
    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; }
        .cartao {
          box-sizing: border-box; width: 356px; height: ${ALTURA[this.estado]}px;
          display: flex; flex-direction: column; overflow: hidden;
          background: var(--cps-surface); border-radius: 12px;
          border-width: 1px; border-style: solid; border-color: var(--cps-border);
        }
        .previa { flex: 1; overflow: hidden; display: flex;
                  align-items: center; justify-content: center;
                  color: var(--cps-textSecondary); }
        .previa img { width: 100%; height: 100%; object-fit: cover; }
        .previa svg { width: 32px; height: 32px; }
        .info { display: flex; align-items: center; gap: 12px; padding: 12px; }
        /* No vazio a mesma linha vira COLUNA centrada: é o que o desenho faz, e é
           o que faz a instrução caber em duas linhas sem empurrar o menu. */
        .cartao.vazio .info { flex-direction: column; justify-content: center;
                              flex: 1; text-align: center; }
        .cartao.vazio .texto { align-items: center; flex: 0; }
        .medalhao { width: 36px; height: 36px; border-radius: 999px;
                    display: flex; align-items: center; justify-content: center;
                    background: var(--cps-primarySubtle); color: var(--cps-primary); }
        .medalhao svg { width: 20px; height: 20px; }
        .texto { display: flex; flex-direction: column; min-width: 0; flex: 1; }
        .nome { color: var(--cps-fg); }
        .meta { color: var(--cps-textSecondary); font-size: var(--cps-type-caption-size, 12px); }
      </style>
      <div class="cartao${vazio ? ' vazio' : ''}" part="cartao">
        ${vazio ? '' : `<div class="previa">${foto ? `<img src="${foto}" alt="">` : ARQUIVO}</div>`}
        <div class="info">
          ${vazio ? `<span class="medalhao">${SETA_ACIMA}</span>` : ''}
          <span class="texto">
            ${vazio
              // A INSTRUÇÃO NÃO SE ELIDE. O corte no meio existe pra nome de arquivo,
              // onde a extensão é a parte que distingue um anexo do outro; aplicado a
              // uma frase ele come o meio dela.
              ? `<span class="nome">${nome}</span>`
              : `<a class="nome" href="${(this.getAttribute('href') || '#').replace(/"/g, '&quot;')}"
               title="${nome.replace(/"/g, '&quot;')}">${DilettaFileCard.elide(nome)}</a>`}
            <span class="meta">${apoio}</span>
          </span>
          ${vazio ? '' : '<slot name="acoes"></slot>'}
        </div>
      </div>`;
  }
}

customElements.define('diletta-file-card', DilettaFileCard);
export { DilettaFileCard, ALTURA };
